/**
 * Office's themes and their Colors, Fonts and Effects schemes, as Excel for
 * Mac ships them (generated by apps/api/scripts/generate_office_theme_catalog.py,
 * which also writes the XLSX writer's copy). Names are Office's own in every
 * language it is localized to; lookups fall back to English.
 */

import source from "./office-theme-catalog.json";

export const OFFICE_THEME_COLOR_SLOTS = [
  "dk1",
  "lt1",
  "dk2",
  "lt2",
  "accent1",
  "accent2",
  "accent3",
  "accent4",
  "accent5",
  "accent6",
  "hlink",
  "folHlink",
] as const;

export type OfficeThemeColorSlot = (typeof OFFICE_THEME_COLOR_SLOTS)[number];
export type OfficeThemeColors = Readonly<Record<OfficeThemeColorSlot, string>>;

/** Scripts whose theme face the editor renders (Chinese, Japanese, Korean). */
export const OFFICE_THEME_FONT_SCRIPTS = ["Hans", "Hant", "Jpan", "Hang"] as const;
export type OfficeThemeFontScript = (typeof OFFICE_THEME_FONT_SCRIPTS)[number];

export interface OfficeThemeFontCollection {
  readonly latin: string;
  readonly ea: string;
  readonly scripts: Readonly<Partial<Record<OfficeThemeFontScript, string>>>;
}

/** Office's name for an entry: English plus each language that differs. */
export type OfficeThemeLabel = Readonly<{ en: string } & Record<string, string>>;

export interface OfficeColorScheme {
  readonly id: string;
  readonly label: OfficeThemeLabel;
  /** The scheme's own name in its XML, which a workbook carries. */
  readonly schemeName: string;
  /** Listed in the Colors gallery (a theme's own colors are not). */
  readonly gallery: boolean;
  readonly colors: OfficeThemeColors;
}

export interface OfficeFontScheme {
  readonly id: string;
  readonly label: OfficeThemeLabel;
  readonly schemeName: string;
  readonly gallery: boolean;
  readonly major: OfficeThemeFontCollection;
  readonly minor: OfficeThemeFontCollection;
}

export interface OfficeEffectStyle {
  readonly shadow: {
    readonly blur: number;
    readonly distance: number;
    readonly direction: number;
    readonly alpha: number;
  } | null;
  readonly glow: boolean;
  readonly reflection: boolean;
  readonly softEdge: boolean;
  readonly bevel: boolean;
}

export interface OfficeEffectScheme {
  readonly id: string;
  /** The theme that carries these effects (none for Office 2007 - 2010). */
  readonly theme: string | null;
  readonly label: OfficeThemeLabel;
  readonly schemeName: string;
  /** {@link officeSchemeSignature} hash of the scheme's XML. */
  readonly signature: string;
  readonly fills: readonly ("solid" | "gradient" | "pattern" | "picture" | "none")[];
  /** Line style widths, EMU. */
  readonly lines: readonly number[];
  readonly effects: readonly OfficeEffectStyle[];
}

export interface OfficeTheme {
  readonly id: string;
  readonly label: OfficeThemeLabel;
  readonly colors: string;
  readonly fonts: string;
  readonly effects: string;
  /** Colors a gallery tile draws: the page ground and its decoration. */
  readonly tile: { readonly background: string; readonly decoration: string | null };
}

interface CatalogSource {
  themes: OfficeTheme[];
  colorSchemes: OfficeColorScheme[];
  fontSchemes: OfficeFontScheme[];
  effectSchemes: OfficeEffectScheme[];
}

const catalog = source as unknown as CatalogSource;

export const OFFICE_THEMES: readonly OfficeTheme[] = Object.freeze(catalog.themes);
export const OFFICE_COLOR_SCHEMES: readonly OfficeColorScheme[] = Object.freeze(
  catalog.colorSchemes,
);
/**
 * The Colors gallery Office shows (Excel's Page Layout > Colors, PowerPoint's
 * Design > Variants > Colors), in Office's order.
 */
export const OFFICE_COLOR_GALLERY: readonly OfficeColorScheme[] = Object.freeze(
  catalog.colorSchemes.filter((scheme) => scheme.gallery),
);

/** One Colors-gallery entry by id, or undefined for anything else. */
export function officeColorGalleryScheme(id: unknown): OfficeColorScheme | undefined {
  return typeof id === "string"
    ? OFFICE_COLOR_GALLERY.find((scheme) => scheme.id === id)
    : undefined;
}
export const OFFICE_FONT_SCHEMES: readonly OfficeFontScheme[] = Object.freeze(
  catalog.fontSchemes,
);
export const OFFICE_EFFECT_SCHEMES: readonly OfficeEffectScheme[] = Object.freeze(
  catalog.effectSchemes,
);

/** One Effects-gallery entry by id (Excel's Page Layout > Effects, PowerPoint's Design > Variants > Effects). */
export function officeEffectGalleryScheme(id: unknown): OfficeEffectScheme | undefined {
  return typeof id === "string" ? OFFICE_EFFECT_SCHEMES.find((scheme) => scheme.id === id) : undefined;
}

/**
 * Office's name in `locale` ("zh", "pt-BR", ...), else English. Each of
 * Office's regional tables is complete, so a region never borrows another's.
 */
export function officeThemeLabel(label: OfficeThemeLabel, locale: string | undefined): string {
  return (locale && label[locale]) || label.en;
}

function qualifiedName(namespace: string | null, local: string): string {
  return namespace ? `{${namespace}}${local}` : local;
}

/**
 * A scheme's content independent of its name, attribute order and
 * formatting; the XLSX reader computes the same string (scheme_signature).
 */
export function officeSchemeSignature(element: Element): string {
  const parts: string[] = [];
  const walk = (node: Element, root: boolean) => {
    parts.push(`<${qualifiedName(node.namespaceURI, node.localName)}`);
    const attributes: [string, string, string][] = [];
    for (const attribute of Array.from(node.attributes)) {
      if (
        attribute.namespaceURI === "http://www.w3.org/2000/xmlns/" ||
        attribute.name === "xmlns" ||
        attribute.name.startsWith("xmlns:")
      ) {
        continue;
      }
      const namespace = attribute.namespaceURI ?? "";
      if (root && !namespace && attribute.localName === "name") continue;
      attributes.push([namespace, attribute.localName, attribute.value]);
    }
    attributes.sort((a, b) =>
      a[0] !== b[0] ? (a[0] < b[0] ? -1 : 1) : a[1] !== b[1] ? (a[1] < b[1] ? -1 : 1) : a[2] < b[2] ? -1 : a[2] > b[2] ? 1 : 0,
    );
    for (const [namespace, local, value] of attributes) {
      parts.push(` ${namespace}|${local}=${value}`);
    }
    parts.push(">");
    const text = Array.from(node.childNodes)
      .filter((child) => child.nodeType === 3 || child.nodeType === 4)
      .map((child) => (child as CharacterData).data)
      .join("")
      .trim();
    if (text) parts.push(text);
    for (const child of Array.from(node.children)) walk(child, false);
    parts.push("</>");
  };
  walk(element, true);
  return parts.join("");
}

/** FNV-1a (64-bit) of a signature, as the catalog stores it. */
export function officeSignatureHash(signature: string): string {
  let value = 0xcbf29ce484222325n;
  for (const byte of new TextEncoder().encode(signature)) {
    value ^= BigInt(byte);
    value = (value * 0x100000001b3n) & 0xffffffffffffffffn;
  }
  return value.toString(16).padStart(16, "0");
}
